waves.point_eqs_eel:
//q1 = state;
//q2 = basstime;

q1 =0;
speed = 1*cos(q2) + bass*0.1;
v = sample*1000 + bass*value1;

//state 0 elipse
xs = xs + sin(v*0.1 + time)*speed;
ys = ys + cos(v*1.2 + q2)*speed;

x = 0.5 + 0.5*cos(xs*0.04 +0.2*time)*sin(time*2 + xs);
y = 0.5 + 0.5*cos(ys*0.04 + 0.4*time)*cos(q2 + xs);


r = r + 0.5*sin(time*4.22);
g = g + 0.5*sin(time*4.307  + (-0.5-x)*(0.5-y));
b = g + 0.5*sin(time*4.959);

x = x*0.75 + 0.125;
y = y*0.75 + 0.125;

xs = if(above(xs,1000),0 ,xs);
ys = if(above(ys,800),0 ,ys);

